int[] a = {2, 4, 1, 3};
int k = 2;
int sum = 0;
for (int i = 0; i < k; i++) sum += a[i];
StringBuilder sb = new StringBuilder();
for (int i = k; i < a.length; i++) {
    sum += a[i] - a[i - k];
    sb.append(sum).append(" ");
}
System.out.println(sb.toString().trim());

int cap = 4, front = 0, rear = 0, size = 0;
int[] buf = new int[cap];
for (int x = 1; x <= 6; x++) {
    buf[rear] = x;
    rear = (rear + 1) % cap;
    if (size < cap) size++;
}
System.out.println(front + " " + rear + " " + buf[front] + " "
        + buf[(front + size - 1) % cap]);

Queue<Integer> q = new ArrayDeque<>();
for (int x : new int[]{1, 2, 3, 4}) q.offer(x);
q.poll();
q.poll();
q.offer(q.poll() + q.peek());
System.out.println(q.peek() * q.size());
